<script setup lang="ts">
import { onMounted, ref, watch } from 'vue'
import { Folder, Download, Pencil, Trash2, FileText, Combine } from 'lucide-vue-next'
type Batch={id:string;name:string;kind:string;device:string;external_id:string|null;count:number;bytes:number;last_at:number}
const props=defineProps<{csrf:string;revision:number}>(), emit=defineEmits<{open:[id:string,name:string];pdf:[id:string];changed:[]}>()
const rows=ref<Batch[]>([]),total=ref(0),page=ref(0),unassigned=ref(0),selected=ref(new Set<string>()),error=ref(''),busy=ref(false)
const labels:Record<string,string>={device:'设备提供',inferred:'按时间推断',manual:'手动整理'}
async function api(path:string,options:RequestInit={}){const response=await fetch(path,{...options,headers:{'Content-Type':'application/json','X-CSRF-Token':props.csrf,...options.headers}});if(!response.ok){const data=await response.json();throw new Error(typeof data.detail==='string'?data.detail:'请求失败')}return response}
async function load(){try{const data=await(await api(`/api/batches?offset=${page.value*50}`)).json();rows.value=data.items;total.value=data.total;unassigned.value=data.unassigned}catch(e){error.value=(e as Error).message}}
onMounted(load);watch(()=>props.revision,load);watch(page,()=>{selected.value=new Set();void load()})
function toggle(id:string){const next=new Set(selected.value);next.has(id)?next.delete(id):next.add(id);selected.value=next}
async function rename(row:Batch){const name=prompt('批次名称',row.name);if(!name?.trim())return;try{await api(`/api/batches/${row.id}`,{method:'PATCH',body:JSON.stringify({name})});await load();emit('changed')}catch(e){error.value=(e as Error).message}}
async function remove(row:Batch){if(!confirm(`将批次“${row.name}”中的全部 ${row.count} 个文件移入回收站？`))return;busy.value=true;try{await api(`/api/batches/${row.id}/delete`,{method:'POST'});await load();emit('changed')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function download(row:Batch){busy.value=true;try{const response=await api(`/api/batches/${row.id}/zip`,{method:'POST'});const a=document.createElement('a');a.href=URL.createObjectURL(await response.blob());a.download=row.name+'.zip';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),30000)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function merge(){const name=prompt('合并后的批次名称','手动合并批次');if(!name?.trim())return;busy.value=true;try{await api('/api/batches/merge',{method:'POST',body:JSON.stringify({ids:[...selected.value],name})});selected.value=new Set();await load();emit('changed')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><section class="batch-browser"><p class="batch-explanation">“按时间推断”仅表示同一来源上传间隔接近，不代表设备确认的扫描任务。可合并批次，或进入批次选择文件拆分。</p><p v-if="error" role="alert" class="banner error">{{error}}</p><div class="batch-toolbar"><span>{{total}} 个批次</span><button :disabled="busy||selected.size<2" @click="merge"><Combine :size="17"/>合并所选批次</button><button v-if="unassigned" @click="emit('open','unassigned','未归类文件')">未归类文件 · {{unassigned}}</button></div><div class="batch-list"><article v-for="row in rows" :key="row.id"><input type="checkbox" :aria-label="'选择批次 '+row.name" :checked="selected.has(row.id)" @change="toggle(row.id)"><button class="batch-title" @click="emit('open',row.id,row.name)"><Folder :size="27"/><div><strong>{{row.name}}</strong><small>{{row.count}} 个文件 · {{row.device}} · {{new Date(row.last_at*1000).toLocaleString('zh-CN')}}</small></div></button><span :class="['batch-kind',row.kind]">{{labels[row.kind]}}</span><div class="batch-actions"><button :disabled="busy" aria-label="批次原件 ZIP" @click="download(row)"><Download :size="17"/></button><button :disabled="busy" aria-label="批次合并 PDF" @click="emit('pdf',row.id)"><FileText :size="17"/></button><button :disabled="busy" aria-label="重命名批次" @click="rename(row)"><Pencil :size="17"/></button><button :disabled="busy" aria-label="删除整个批次" @click="remove(row)"><Trash2 :size="17"/></button></div></article><p v-if="!rows.length" class="empty">暂无扫描批次；新上传文件将自动归类。</p></div><footer class="pagination"><span>第 {{page+1}} 页</span><div><button :disabled="page===0" @click="page--">上一页</button><button :disabled="(page+1)*50>=total" @click="page++">下一页</button></div></footer></section></template>
